create table public.member_profile_patches(
 id uuid primary key default gen_random_uuid(),
 member_id uuid not null references public.members(id),
 schema_version text not null references public.member_profile_catalog(schema_version),
 revision bigint not null check(revision>0),
 patch jsonb not null check(jsonb_typeof(patch)='object' and octet_length(patch::text)<=262144),
 source_key text not null check(length(source_key) between 1 and 200),
 request_hash text not null check(request_hash ~ '^[a-f0-9]{64}$'),
 mode text not null check(mode in ('registrar','corrigir')),
 reason text not null check(length(reason) between 1 and 1000),
 created_by jsonb not null check(jsonb_typeof(created_by)='object'),
 created_at timestamptz not null default now(),
 unique(member_id,revision),unique(member_id,source_key)
);
alter table public.member_profile_catalog enable row level security;
alter table public.member_profile_patches enable row level security;
revoke all on public.member_profile_catalog,public.member_profile_patches from anon,authenticated,service_role;
grant select on public.member_profile_catalog,public.member_profile_patches to authenticated,service_role;
grant insert on public.member_profile_patches to service_role;
create policy profile_catalog_admin_read on public.member_profile_catalog for select to authenticated using((select public.is_admin()));
create policy profile_patches_admin_read on public.member_profile_patches for select to authenticated using((select public.is_admin()));

create function member_profile_private.valid_reference(v jsonb) returns boolean
language plpgsql immutable security invoker set search_path='' as $$
declare k text; s text; parsed date;
begin
 if jsonb_typeof(v)<>'object' or v-array['inicio','fim','precisao','natureza']<>'{}'::jsonb
  or coalesce(v->>'precisao','') not in ('dia','mes','intervalo','desconhecida')
  or (v->'natureza' is not null and v->'natureza'<>'null'::jsonb and v->>'natureza' not in ('fato','documento')) then return false;end if;
 for k in select unnest(array['inicio','fim']) loop
  if v ? k and v->k<>'null'::jsonb then
   if jsonb_typeof(v->k)<>'string' then return false;end if;s=v->>k;
   if s!~'^[0-9]{4}-[0-9]{2}(-[0-9]{2})?$' then return false;end if;
   parsed=(case when length(s)=7 then s||'-01' else s end)::date;
  end if;
 end loop;
 return not(v->>'inicio' is not null and v->>'fim' is not null and v->>'fim'<v->>'inicio');
exception when invalid_datetime_format or datetime_field_overflow then return false;
end;$$;
create function member_profile_private.valid_record(v jsonb,t text,c jsonb) returns boolean
language plpgsql immutable security invoker set search_path='' as $$
declare k text; d jsonb;
begin
 if jsonb_typeof(v)<>'object' or v-array['id','estado','campos']<>'{}'::jsonb or jsonb_typeof(v->'id')<>'string'
  or (v->>'id')!~'^[a-zA-Z0-9_-]{1,120}$' or coalesce(v->>'estado','') not in ('atual','historico','removido','a_confirmar')
  or jsonb_typeof(v->'campos')<>'object' or c->'records'->t is null then return false; end if;
 if (select count(*) from jsonb_object_keys(v->'campos'))<>(select count(*) from jsonb_object_keys(c->'records'->t->'fields')) then return false; end if;
 for k,d in select * from jsonb_each(c->'records'->t->'fields') loop
  if not coalesce(member_profile_private.valid_field(v->'campos'->k,d,c),false) then return false; end if;
 end loop;
 return true;
end;$$;
create function member_profile_private.valid_field(f jsonb,d jsonb,c jsonb) returns boolean
language plpgsql immutable security invoker set search_path='' as $$
declare v jsonb; x jsonb; k text; kind text;
begin
 if f is null or d is null or jsonb_typeof(f)<>'object' then return false; end if;
 if f-array['valor','situacao','natureza','fontes_refs','data_referencia','justificativa','updated_at','updated_by','alternativas','historicos']<>'{}'::jsonb
  or not(f ?& array['valor','situacao','natureza','fontes_refs','data_referencia'])
  or coalesce(f->>'situacao','') not in ('informado','nao_informado','nao_aplicavel','a_confirmar')
  or (f->'natureza'<>'null'::jsonb and f->>'natureza' not in ('declarado','pesquisado','medido'))
  or jsonb_typeof(f->'fontes_refs')<>'array' or jsonb_array_length(f->'fontes_refs')>50
  or not coalesce(member_profile_private.valid_reference(f->'data_referencia'),false)
  or coalesce(f->'alternativas','[]'::jsonb)<>'[]'::jsonb or coalesce(f->'historicos','[]'::jsonb)<>'[]'::jsonb then return false; end if;
 if exists(select 1 from jsonb_array_elements(f->'fontes_refs') a where jsonb_typeof(a)<>'string') then return false; end if;
 if f->>'situacao'='informado' and jsonb_array_length(f->'fontes_refs')=0 then return false; end if;
 if f->>'situacao'='nao_aplicavel' and coalesce(f->>'justificativa','')='' then return false; end if;
 if f ? 'justificativa' and f->'justificativa'<>'null'::jsonb and (jsonb_typeof(f->'justificativa')<>'string' or length(f->>'justificativa')>12000) then return false;end if;
 v=f->'valor';kind=d->>'kind';
 if f->>'situacao' in ('nao_informado','nao_aplicavel') then return v='null'::jsonb; end if;
 if v='null'::jsonb then return f->>'situacao'='a_confirmar'; end if;
 if kind='text' then return jsonb_typeof(v)='string' and length(v#>>'{}')<=12000; end if;
 if kind='date' then return jsonb_typeof(v)='string' and member_profile_private.valid_reference(jsonb_build_object('inicio',v#>>'{}','fim',null,'precisao','dia','natureza',null));end if;
 if kind='boolean' then return jsonb_typeof(v)='boolean'; end if;
 if kind='enum' then return jsonb_typeof(v)='string' and (d->'choices') ? (v#>>'{}'); end if;
 if kind='text_list' then
  if jsonb_typeof(v)<>'array' or jsonb_array_length(v)>200 then return false; end if;
  return not exists(select 1 from jsonb_array_elements(v) a where jsonb_typeof(a)<>'string' or length(a#>>'{}')>12000);
 end if;
 if kind='metric' then
  if jsonb_typeof(v)<>'object' or v-array['tipo_valor','numero','minimo','maximo','texto_original','unidade','precisao','periodo','escopo','vinculo_id']<>'{}'::jsonb
   or coalesce(v->>'tipo_valor','') not in ('numero','faixa','texto') then return false; end if;
  if coalesce(case when v ? 'precisao' then v->>'precisao' else 'nao_definida' end,'') not in ('exata','aproximada','faixa','nao_definida')
   or coalesce(case when v ? 'escopo' then v->>'escopo' else 'nao_definido' end,'') not in ('geral_negocio','vinculo','nao_definido') then return false;end if;
  for k in select unnest(array['numero','minimo','maximo']) loop
   if v ? k and v->k<>'null'::jsonb then
    if jsonb_typeof(v->k)<>'number' then return false;end if;
    if abs((v->>k)::numeric)>1.7976931348623157e308::numeric then return false;end if;
   end if;
  end loop;
  for k in select unnest(array['texto_original','unidade','vinculo_id']) loop
   if v ? k and v->k<>'null'::jsonb and (jsonb_typeof(v->k)<>'string' or length(v->>k)>12000) then return false;end if;
  end loop;
  if v->>'escopo'='vinculo' and coalesce(v->>'vinculo_id','')='' then return false;end if;
  if v ? 'periodo' and v->'periodo'<>'null'::jsonb and not coalesce(member_profile_private.valid_reference(v->'periodo'),false) then return false;end if;
  if v->>'tipo_valor'='numero' then return jsonb_typeof(v->'numero')='number'; end if;
  if v->>'tipo_valor'='faixa' then return jsonb_typeof(v->'minimo')='number' and jsonb_typeof(v->'maximo')='number' and (v->>'minimo')::numeric<=(v->>'maximo')::numeric; end if;
  return jsonb_typeof(v->'texto_original')='string' and length(v->>'texto_original')>0;
 end if;
 if kind='record' then return member_profile_private.valid_record(v,d->>'item_type',c); end if;
 if kind='list' then
  if jsonb_typeof(v)<>'array' or jsonb_array_length(v)>200 then return false; end if;
  for x in select * from jsonb_array_elements(v) loop if not member_profile_private.valid_record(x,d->>'item_type',c) then return false; end if; end loop;
  return (select count(*)=count(distinct a->>'id') from jsonb_array_elements(v) a);
 end if;
 return false;
end;$$;

create function public.member_profile_apply(p_member_id uuid,p_schema_version text,p_expected_revision bigint,p_patch jsonb,p_source_key text,p_mode text,p_actor jsonb,p_reason text) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare c jsonb; r public.member_profile_patches; rev bigint; h text; k text; f jsonb; d jsonb; ref jsonb;
begin
 if p_expected_revision is null or p_expected_revision<0 or p_mode not in ('registrar','corrigir') or jsonb_typeof(p_patch)<>'object' or p_patch='{}'::jsonb
  or octet_length(p_patch::text)>262144 or length(p_source_key) not between 1 and 200 or length(p_reason) not between 1 and 1000
  or jsonb_typeof(p_actor)<>'object' or coalesce(p_actor->>'tipo','') not in ('agente','equipe') or jsonb_typeof(p_actor->'id')<>'string' or coalesce(p_actor->>'id','')='' then raise exception 'invalid profile update'; end if;
 if not exists(select 1 from public.members where id=p_member_id) then raise exception 'unknown member'; end if;
 perform pg_advisory_xact_lock(hashtextextended('profile:'||p_member_id::text,0));
 select definition into c from public.member_profile_catalog where schema_version=p_schema_version;if c is null then raise exception 'unknown profile version';end if;
 h=encode(sha256(convert_to(jsonb_build_object('patch',p_patch,'mode',p_mode,'actor',p_actor,'reason',p_reason)::text,'UTF8')),'hex');
 select * into r from public.member_profile_patches where member_id=p_member_id and source_key=p_source_key;
 if found then return jsonb_build_object('status',case when r.request_hash=h then 'duplicate' else 'conflict' end,'revision',r.revision,'id',r.id);end if;
 select coalesce(max(revision),0) into rev from public.member_profile_patches where member_id=p_member_id;
 if rev<>p_expected_revision then return jsonb_build_object('status','revision_conflict','revision',rev);end if;
 for k,f in select * from jsonb_each(p_patch) loop
  d=c->'fields'->k;
  if d is null or d ? 'canonical' or coalesce((d->>'readonly')::boolean,false) or not coalesce(member_profile_private.valid_field(f,d,c),false) then raise exception 'invalid profile field: %',k;end if;
 end loop;
 for ref in select * from jsonb_path_query(p_patch,'$.** ? (exists(@.valor) && exists(@.situacao)).fontes_refs[*]') loop
  if jsonb_typeof(ref)<>'string' or (ref#>>'{}')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then raise exception 'fonte inválida';end if;
  if not exists(select 1 from public.member_context_entries where id=(ref#>>'{}')::uuid and member_id=p_member_id) then raise exception 'fonte de outro mentorado';end if;
 end loop;
 insert into public.member_profile_patches(member_id,schema_version,revision,patch,source_key,request_hash,mode,reason,created_by)
 values(p_member_id,p_schema_version,rev+1,p_patch,p_source_key,h,p_mode,p_reason,p_actor) returning * into r;
 return jsonb_build_object('status','created','revision',r.revision,'id',r.id);
end;$$;

-- Existing Cérebro data is private and not exposed to PostgREST roles. Keep
-- that boundary: this narrow definer is non-exposed, service-only, and returns
-- counts for one member. It never grants runtime SELECT on messages/tokens.
create function member_profile_private.connection_counts(p_member_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if current_setting('role',true) not in ('service_role','postgres') then raise insufficient_privilege;end if;
 return jsonb_build_object('instagram_contas',(select count(*) from cerebro.instagram_contas where member_id=p_member_id and ativo),
  'instagram_metricas',(select count(*) from cerebro.instagram_metricas m join cerebro.instagram_contas c on c.ig_user_id=m.ig_user_id where c.member_id=p_member_id and c.ativo),
  'grupos_whatsapp',(select count(*) from cerebro.grupos where member_id=p_member_id and ativo),'checked_at',now());
end;$$;
create function public.member_profile_connections(p_member_id uuid) returns jsonb
language sql stable security invoker set search_path='' as $$ select member_profile_private.connection_counts(p_member_id);$$;
create function public.member_profile_directory(p_incluir_inativos boolean default false)
returns table(id uuid,nome text,ativo boolean,fontes bigint,formularios bigint,revision bigint)
language sql stable security invoker set search_path='' as $$
 select m.id,m.nome,m.ativo,
  (select count(*) from public.member_context_entries e where e.member_id=m.id),
  (select count(*) from public.member_context_entries e where e.member_id=m.id and e.source_type='pre_diagnostico'),
  (select coalesce(max(p.revision),0) from public.member_profile_patches p where p.member_id=m.id)
 from public.members m where (p_incluir_inativos or m.ativo) order by m.nome,m.id;
$$;
revoke all on all functions in schema member_profile_private from public,anon,authenticated;
grant execute on all functions in schema member_profile_private to service_role;
revoke all on function public.member_profile_apply(uuid,text,bigint,jsonb,text,text,jsonb,text),public.member_profile_connections(uuid),public.member_profile_directory(boolean) from public,anon,authenticated;
grant execute on function public.member_profile_apply(uuid,text,bigint,jsonb,text,text,jsonb,text),public.member_profile_connections(uuid),public.member_profile_directory(boolean) to service_role;
comment on table public.member_profile_patches is 'Atualizações estruturadas append-only do perfil2.0. Fontes originais permanecem em member_context_entries.';
commit;
